#!/usr/bin/env node
// SPEC-DEVICE: generate per-class reference pages from the normative registry.
// Regenerated by `npm run generate:device-registry`. Do not edit the pages by hand.
import {
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const ROOT = join(here, "..");
const REGISTRY_PATH = join(
  ROOT,
  "specs",
  "spec-device",
  "registry",
  "device-classes.json",
);
export const DEVICE_CLASS_PAGES_DIR = join(ROOT, "docs", "device-classes");

function capabilityId(classId, suffix) {
  return suffix === null || suffix === undefined
    ? `device:${classId}`
    : `device:${classId}:${suffix}`;
}

function formatBps(value) {
  if (value >= 1_000_000) return `${value / 1_000_000} Mbps`;
  if (value >= 1_000) return `${value / 1_000} kbps`;
  return `${value} bps`;
}

function bandwidthRows(entry) {
  const rows = [];
  for (const [tierId, profile] of Object.entries(entry.bandwidth)) {
    rows.push(
      `| \`${tierId}\` | ${formatBps(profile.minBps)} | ${formatBps(profile.targetBps)} | ${profile.burstBytes} | — |`,
    );
    for (const [encoding, encoded] of Object.entries(profile.encodings ?? {})) {
      rows.push(
        `| \`${tierId}\` / \`${encoding}\` | ${formatBps(encoded.minBps)} | ${formatBps(encoded.targetBps)} | ${encoded.burstBytes} | encoding |`,
      );
    }
  }
  return rows;
}

function pageFor(entry) {
  const tiers = entry.tiers
    .map((tier) => {
      const cap = capabilityId(entry.id, tier.capabilitySuffix);
      const def = tier.default ? "yes" : "no";
      return `| \`${tier.id}\` | ${def} | ${tier.consentClass} | \`${cap}\` |`;
    })
    .join("\n");
  const duty =
    entry.defaults.dutyCycle === undefined
      ? "—"
      : String(entry.defaults.dutyCycle);
  const stream = entry.streamable ? "yes" : "no";
  const remote = entry.remoteEligible ? "yes" : "no";
  const ladder = entry.degradationLadder
    .map((rung) => `- \`${rung}\``)
    .join("\n");
  return `# Device class: ${entry.id}

<!-- tp-doc
lifecycle: reference
audited: 2026-08-18
register: none
-->

Generated by \`scripts/generate-device-class-pages.mjs\` from
[\`device-classes.json\`](../../specs/spec-device/registry/device-classes.json).
Do not edit. Companion: [Device I/O](../device-io.md), [SPEC-DEVICE](../../specs/spec-device/spec.md),
[add a device class](../device-class-runbook.md).

${entry.description}

## 1. Role

| Field | Value |
| ----- | ----- |
| Role | ${entry.role} |
| Consent class | ${entry.consentClass} |
| Added in host API | ${entry.addedInHostApi} |
| Sample schema | \`${entry.sampleSchema}\` |

## 2. Tiers

Capability ids follow \`device:<class>\` for the default tier and
\`device:<class>:<suffix>\` for elevated tiers. Unknown strings still fail closed.

| Tier | Default | Consent | Capability |
| ---- | ------- | ------- | ---------- |
${tiers}

## 3. Data flow

Control (\`open\`, \`close\`, \`configure\`, \`read\`, low-rate \`subscribe\`) stays on the
broker. Sample data uses the device stream sidecar after the broker authorizes a
session. Preview surfaces the host draws are not readable back by the sandbox.

| Field | Value |
| ----- | ----- |
| Streamable to a peer | ${stream} |
| Remote-eligible | ${remote} |
| Max rate | ${entry.defaults.maxRateHz} Hz |
| Session TTL | ${entry.defaults.maxSessionMs} ms |
| Duty cycle | ${duty} |

Streaming additionally requires \`device:stream\`. A peer acquiring this class on
this host additionally requires \`device:remote\` on the requesting side and a
host-owned remote grant on the serving side.

## 4. Bandwidth

Admission uses these profiles against current link supply. Encodings, when present,
are rungs on the class degradation ladder.

| Profile | Min | Target | Burst (bytes) | Kind |
| ------- | --- | ------ | ------------- | ---- |
${bandwidthRows(entry).join("\n")}

## 5. Degradation ladder

Highest fidelity first. Admission walks down this list when supply cannot hold
the current rung.

${ladder}
`;
}

function indexPage(classes) {
  const rows = classes
    .map((entry) => {
      const cap = capabilityId(
        entry.id,
        entry.tiers.find((tier) => tier.default)?.capabilitySuffix ?? null,
      );
      return `| [\`${entry.id}\`](${entry.id}.md) | ${entry.role} | ${entry.consentClass} | \`${cap}\` | ${entry.streamable ? "yes" : "no"} | ${entry.remoteEligible ? "yes" : "no"} |`;
    })
    .join("\n");
  return `# Device class reference

<!-- tp-doc
lifecycle: reference
audited: 2026-08-18
register: none
-->

Generated by \`scripts/generate-device-class-pages.mjs\` from
[\`device-classes.json\`](../../specs/spec-device/registry/device-classes.json).
Do not edit. One page per registry class, in the same reference shape as
[ble-interface.md](../ble-interface.md): role, tiers, data flow, bandwidth, ladder.

The registry is the growth mechanism — adding a class is a registry entry plus a
driver, then \`npm run generate:device-registry\`. See
[add a device class](../device-class-runbook.md) and [Device I/O](../device-io.md).

| Class | Role | Consent | Default capability | Stream | Remote |
| ----- | ---- | ------- | ------------------ | ------ | ------ |
${rows}
`;
}

export function deviceClassPagePaths(classes) {
  return [
    "docs/device-classes/README.md",
    ...classes.map((entry) => `docs/device-classes/${entry.id}.md`),
  ];
}

export function generateDeviceClassPages(registryPath = REGISTRY_PATH) {
  const registry = JSON.parse(readFileSync(registryPath, "utf8"));
  const classes = registry.classes;
  mkdirSync(DEVICE_CLASS_PAGES_DIR, { recursive: true });
  const keep = new Set([
    "README.md",
    ...classes.map((entry) => `${entry.id}.md`),
  ]);
  for (const name of readdirSync(DEVICE_CLASS_PAGES_DIR)) {
    if (!keep.has(name)) rmSync(join(DEVICE_CLASS_PAGES_DIR, name));
  }
  writeFileSync(join(DEVICE_CLASS_PAGES_DIR, "README.md"), indexPage(classes));
  for (const entry of classes) {
    writeFileSync(
      join(DEVICE_CLASS_PAGES_DIR, `${entry.id}.md`),
      pageFor(entry),
    );
  }
  return { classCount: classes.length, paths: deviceClassPagePaths(classes) };
}

const invokedDirectly =
  process.argv[1] !== undefined &&
  fileURLToPath(import.meta.url) ===
    (await import("node:path")).resolve(process.argv[1]);
if (invokedDirectly) {
  const result = generateDeviceClassPages();
  console.log(
    `generated ${result.classCount} device-class pages → ${DEVICE_CLASS_PAGES_DIR}`,
  );
}
